insert into public.cles_examen (module_id, question, reponse, explication) values
('n1m1', 0, 'La mort', '« Car le salaire du péché, c''est la mort ; mais le don gratuit de Dieu, c''est la vie éternelle » (Romains 6.23).'),
('n1m1', 1, 'Manquer la cible, s''écarter du but', 'Chatta''t évoque l''idée de manquer le but ; le même verbe est employé pour des frondeurs qui ne manquaient pas le but (Juges 20.16).'),
('n1m1', 2, 'Semer le doute sur la parole de Dieu : « Dieu a-t-il réellement dit ? »', 'Le serpent commence par mettre en doute la parole de Dieu, puis accuse Dieu de mentir (Genèse 3.1-5).'),
('n1m1', 3, 'Nathan', 'Dieu envoie Nathan, qui raconte la parabole de la petite brebis et dit à David : « Tu es cet homme-là ! » (2 Samuel 12.1-7).'),
('n1m1', 4, '« J''ai péché contre l''Éternel ! »', 'David reconnaît sa faute sans excuse : « J''ai péché contre l''Éternel ! » et Nathan lui annonce le pardon (2 Samuel 12.13).'),
('n1m1', 5, 'Nos crimes et nos péchés', '« Ce sont vos crimes qui mettent une séparation entre vous et votre Dieu » ; la main de l''Éternel n''est pas trop courte pour sauver (Ésaïe 59.1-2).'),
('n1m1', 6, 'Juifs et Grecs sont tous sous l''empire du péché', 'Paul conclut que « Juifs et Grecs, sont tous sous l''empire du péché » et que nul n''est juste (Romains 3.9-10).'),
('n1m1', 7, 'Faire connaître le péché', '« C''est par la loi que vient la connaissance du péché » : la Loi montre la maladie comme un miroir, elle ne la guérit pas (Romains 3.20).'),
('n1m1', 8, 'Par la grâce, par le moyen de la foi', '« C''est par la grâce que vous êtes sauvés, par le moyen de la foi… ce n''est point par les œuvres » (Éphésiens 2.8-9).'),
('n1m1', 9, 'Elles sont le fruit du salut : nous avons été créés en Christ pour les pratiquer', 'Nous sommes « créés en Jésus-Christ pour de bonnes œuvres, que Dieu a préparées d''avance » : sauvés non par les œuvres, mais pour les œuvres.'),
('n1m1', 10, '« Souviens-toi de moi, quand tu viendras dans ton règne »', 'Il dit : « Souviens-toi de moi, quand tu viendras dans ton règne », et Jésus lui promet : « aujourd''hui tu seras avec moi dans le paradis » (Luc 23.42-43).'),
('n1m1', 11, 'Que le salut est reçu par la foi, comme un don, sans mérite', 'Le brigand n''avait aucune œuvre à offrir ; il a cru et Jésus l''a sauvé le jour même (Luc 23.40-43).'),
('n1m1', 12, 'Changer de pensée et de direction : quitter le péché pour se tourner vers Dieu', 'Metanoia signifie un changement de pensée qui entraîne un changement de direction ; Jésus dit : « Repentez-vous, et croyez à la bonne nouvelle » (Marc 1.15).'),
('n1m1', 13, 'Le propitiatoire, lieu où le sang du sacrifice couvrait le péché', 'Hilastêrion désigne le propitiatoire de l''arche (Lévitique 16) ; Jésus est celui en qui la juste colère de Dieu contre le péché est apaisée.'),
('n1m1', 14, 'Faux', 'Faux : « Dieu prouve son amour envers nous, en ce que, lorsque nous étions encore des pécheurs, Christ est mort pour nous » (Romains 5.8).'),
('n1m1', 15, 'Pharisien, chef des Juifs et docteur d''Israël', 'Nicodème était pharisien, chef des Juifs, et Jésus l''appelle « le docteur d''Israël » (Jean 3.1, 10).'),
('n1m1', 16, 'Le serpent d''airain élevé par Moïse dans le désert', '« Comme Moïse éleva le serpent dans le désert, il faut de même que le Fils de l''homme soit élevé, afin que quiconque croit en lui ait la vie éternelle » (Jean 3.14-15 ; Nombres 21.4-9).'),
('n1m1', 17, 'Pour que les croyants sachent qu''ils ont la vie éternelle', '« Je vous ai écrit ces choses, afin que vous sachiez que vous avez la vie éternelle, vous qui croyez au nom du Fils de Dieu » (1 Jean 5.13).'),
('n1m1', 18, '« Ton assurance repose sur la promesse de Dieu : celui qui a le Fils a la vie »', 'L''assurance repose d''abord sur la Parole de Dieu, qui ne change pas : « Celui qui a le Fils a la vie » (1 Jean 5.12).'),
('n1m1', 19, 'Confesser son péché, car Dieu est fidèle et juste pour le pardonner et le purifier', '« Si nous confessons nos péchés, il est fidèle et juste pour nous les pardonner, et pour nous purifier de toute iniquité » (1 Jean 1.9).'),
('n1m2', 0, 'Un seul Dieu en trois personnes : Père, Fils et Saint-Esprit', '« L''Éternel, notre Dieu, est le seul Éternel » (Deutéronome 6.4), et ce Dieu unique se révèle comme Père, Fils et Saint-Esprit (Matthieu 28.19).'),
('n1m2', 1, 'Comme un Dieu miséricordieux et compatissant, lent à la colère, riche en bonté et en fidélité', '« L''Éternel, l''Éternel, Dieu miséricordieux et compatissant, lent à la colère, riche en bonté et en fidélité » (Exode 34.6).'),
('n1m2', 2, 'L''amour fidèle et loyal de l''alliance', 'Chesed désigne l''amour loyal de l''alliance, un amour qui ne lâche pas l''autre (Exode 34.6 ; Psaume 103.8).'),
('n1m2', 3, 'Comme un père a compassion de ses enfants', '« Comme un père a compassion de ses enfants, l''Éternel a compassion de ceux qui le craignent » (Psaume 103.13).'),
('n1m2', 4, 'Il est ému de compassion, il court se jeter à son cou et le baise', '« Comme il était encore loin, son père le vit et fut ému de compassion, il courut se jeter à son cou et le baisa » (Luc 15.20).'),
('n1m2', 5, 'Aux pharisiens et aux scribes qui murmuraient parce qu''il accueillait les pécheurs', 'Les pharisiens murmuraient : « Cet homme accueille des gens de mauvaise vie, et il mange avec eux » ; le fils aîné de la parabole les représente (Luc 15.1-2, 25-32).'),
('n1m2', 6, 'Père, avec une nuance d''intimité familiale', 'Abba est le mot de l''intimité familiale pour « Père » (Marc 14.36) ; l''Esprit nous fait crier « Abba ! Père ! » (Romains 8.15).'),
('n1m2', 7, 'La Parole éternelle, qui était Dieu, faite chair', '« La Parole était Dieu… Et la parole a été faite chair, et elle a habité parmi nous » (Jean 1.1, 14).'),
('n1m2', 8, 'Dresser sa tente', 'Skênoô signifie « dresser sa tente » et rappelle le tabernacle où habitait la gloire de Dieu : en Jésus, Dieu est venu habiter parmi nous.'),
('n1m2', 9, '« Quel est donc celui-ci, à qui obéissent même le vent et la mer ? »', 'Ils furent saisis d''une grande frayeur et se dirent : « Quel est donc celui-ci, à qui obéissent même le vent et la mer ? » (Marc 4.41).'),
('n1m2', 10, '« Mon Seigneur et mon Dieu ! »', 'Thomas confesse : « Mon Seigneur et mon Dieu ! » (Jean 20.28), et Jésus accepte cette adoration.'),
('n1m2', 11, 'En se dépouillant, prenant une forme de serviteur et obéissant jusqu''à la mort de la croix', 'Existant en forme de Dieu, il s''est dépouillé, a pris une forme de serviteur, et s''est rendu obéissant jusqu''à la mort de la croix (Philippiens 2.6-8).'),
('n1m2', 12, 'Seul Dieu peut sauver, et il fallait un homme pour mourir à la place des hommes', 'Seul Dieu peut sauver (Ésaïe 43.11), et c''est un homme qui devait réparer ce qu''Adam avait détruit et mourir à notre place (Romains 5.19 ; Hébreux 2.17).'),
('n1m2', 13, 'Il est toujours vivant pour intercéder en faveur de ceux qui s''approchent de Dieu par lui', '« Il peut sauver parfaitement ceux qui s''approchent de Dieu par lui, étant toujours vivant pour intercéder en leur faveur » (Hébreux 7.25).'),
('n1m2', 14, 'Faux', 'Faux : « Si tu confesses de ta bouche le Seigneur Jésus… tu seras sauvé » (Romains 10.9). Jésus est à la fois Sauveur et Seigneur.'),
('n1m2', 15, 'Une personne divine qui parle, enseigne et peut être attristée', 'L''Esprit parle (Actes 13.2), enseigne (Jean 14.26), peut être attristé (Éphésiens 4.30) et mentir au Saint-Esprit, c''est mentir à Dieu (Actes 5.3-4).'),
('n1m2', 16, 'Celui qui est appelé à côté : avocat, défenseur, aide', 'Paraklêtos signifie « appelé à côté » : l''Esprit vient à nos côtés comme avocat, défenseur et aide (Jean 14.16-17).'),
('n1m2', 17, 'Du péché, de la justice et du jugement', '« Il convaincra le monde en ce qui concerne le péché, la justice, et le jugement » (Jean 16.8).'),
('n1m2', 18, 'La prophétie de Joël : « Je répandrai de mon Esprit sur toute chair »', 'Pierre cite Joël 2.28-32 : « Dans les derniers jours, dit Dieu, je répandrai de mon Esprit sur toute chair » (Actes 2.16-17).'),
('n1m2', 19, 'L''Esprit glorifie Jésus, ne contredit pas l''Écriture, et le don de Dieu ne s''achète pas', 'L''Esprit glorifie Christ (Jean 16.14) ; il faut tout éprouver (1 Thessaloniciens 5.21), et Pierre condamne Simon qui pensait acquérir le don de Dieu à prix d''argent (Actes 8.20).'),
('n1m3', 0, '66', 'La Bible protestante compte 66 livres : 39 dans l''Ancien Testament et 27 dans le Nouveau Testament.'),
('n1m3', 1, 'Soufflée par Dieu', 'Theopneustos vient de theos (Dieu) et pneô (souffler) : l''Écriture est « soufflée par Dieu » (2 Timothée 3.16).'),
('n1m3', 2, 'Enseigner, convaincre, corriger, instruire dans la justice', '« Toute Écriture est inspirée de Dieu, et utile pour enseigner, pour convaincre, pour corriger, pour instruire dans la justice » (2 Timothée 3.16).'),
('n1m3', 3, 'Poussés par le Saint-Esprit, de la part de Dieu', '« Ce n''est pas par une volonté d''homme qu''une prophétie a jamais été apportée, mais c''est poussés par le Saint-Esprit que des hommes ont parlé de la part de Dieu » (2 Pierre 1.21).'),
('n1m3', 4, 'Josias', 'Le grand prêtre Hilkija trouva le livre de la loi pendant les réparations du temple, la dix-huitième année du roi Josias (2 Rois 22.3-8).'),
('n1m3', 5, 'Il déchira ses vêtements et s''humilia devant l''Éternel', '« Lorsque le roi entendit les paroles du livre de la loi, il déchira ses vêtements » (2 Rois 22.11) ; Dieu vit qu''il s''était humilié (22.19).'),
('n1m3', 6, 'Il le découpa et le jeta au feu', 'Jojakim coupa les colonnes du rouleau et les jeta au feu ; mais Dieu fit écrire un autre rouleau avec les mêmes paroles (Jérémie 36.23, 28).'),
('n1m3', 7, 'Vivante et efficace, plus tranchante qu''une épée à deux tranchants', '« La parole de Dieu est vivante et efficace, plus tranchante qu''une épée quelconque à deux tranchants… elle juge les sentiments et les pensées du cœur » (Hébreux 4.12).'),
('n1m3', 8, 'Trois : l''hébreu, l''araméen et le grec', 'L''Ancien Testament a été écrit surtout en hébreu, avec quelques passages en araméen, et le Nouveau Testament en grec.'),
('n1m3', 9, 'Le chapitre', '« Jean 3.16 » signifie : livre de Jean, chapitre 3, verset 16.'),
('n1m3', 10, '27', 'Le Nouveau Testament compte 27 livres : 4 Évangiles, les Actes, 13 lettres de Paul, 8 autres lettres et l''Apocalypse.'),
('n1m3', 11, 'Genèse, Exode, Lévitique, Nombres, Deutéronome', 'Le Pentateuque, ou livres de Moïse, comprend la Genèse, l''Exode, le Lévitique, les Nombres et le Deutéronome.'),
('n1m3', 12, 'Commençant par Moïse et tous les prophètes, il leur expliqua dans toutes les Écritures ce qui le concernait', '« Commençant par Moïse et par tous les prophètes, il leur expliqua dans toutes les Écritures ce qui le concernait » (Luc 24.27).'),
('n1m3', 13, 'Faux', 'Faux : Jésus dit des Écritures « ce sont elles qui rendent témoignage de moi » (Jean 5.39) ; l''Ancien Testament l''annonce, le Nouveau le révèle.'),
('n1m3', 14, 'Une lampe à mes pieds et une lumière sur mon sentier', '« Ta parole est une lampe à mes pieds, et une lumière sur mon sentier » (Psaume 119.105).'),
('n1m3', 15, 'Murmurer, répéter, ruminer la Parole', 'Hagah signifie murmurer, prononcer à mi-voix, ruminer : méditer, c''est garder la Parole en bouche et dans le cœur pour agir fidèlement (Josué 1.8).'),
('n1m3', 16, 'Étudier, mettre en pratique, puis enseigner', 'Esdras « avait appliqué son cœur à étudier et à mettre en pratique la loi de l''Éternel, et à enseigner au milieu d''Israël » (Esdras 7.10).'),
('n1m3', 17, 'Ils en donnaient le sens pour faire comprendre ce qu''on avait lu', '« Ils lisaient distinctement dans le livre de la loi de Dieu, et ils en donnaient le sens pour faire comprendre ce qu''ils avaient lu » (Néhémie 8.8).'),
('n1m3', 18, 'À un homme qui se regarde dans un miroir et oublie aussitôt son visage', 'Il est « semblable à un homme qui regarde dans un miroir son visage naturel, et qui, après s''être regardé, s''en va, et oublie aussitôt quel il était » (Jacques 1.23-24).'),
('n1m3', 19, 'Vérifier le verset cité dans la Bible et lire tout le passage autour, comme les Béréens', 'Les Béréens « examinaient chaque jour les Écritures, pour voir si ce qu''on leur disait était exact » (Actes 17.11) ; il faut lire chaque verset dans son contexte.'),
('n1m4', 0, 'De prier pour être vus des hommes', 'Ils prient pour être vus des hommes et ont déjà reçu leur récompense ; Jésus invite à prier le Père dans le secret (Matthieu 6.5-6).'),
('n1m4', 1, 'Parce que le Père sait de quoi nous avons besoin avant que nous le lui demandions', 'Les païens pensaient être exaucés à force de paroles ; mais « votre Père sait de quoi vous avez besoin, avant que vous le lui demandiez » (Matthieu 6.8).'),
('n1m4', 2, 'Des demandes tournées vers Dieu : son nom, son règne, sa volonté', 'Le modèle de Jésus commence par Dieu : que ton nom soit sanctifié, que ton règne vienne, que ta volonté soit faite (Matthieu 6.9-10).'),
('n1m4', 3, 'Dettes', 'Le mot opheilêmata signifie « dettes » : le péché est une dette envers Dieu, que lui seul peut remettre (Matthieu 6.12).'),
('n1m4', 4, 'Les faire connaître à Dieu par la prière, avec des actions de grâces', 'Paul invite à faire connaître nos besoins à Dieu par des prières et des supplications, avec des actions de grâces ; la paix de Dieu gardera alors nos cœurs (Philippiens 4.6-7).'),
('n1m4', 5, 'Ses lèvres remuent mais on n''entend pas sa voix', 'Anne parlait dans son cœur ; seules ses lèvres remuaient. Elle explique : « je répandais mon âme devant l''Éternel » (1 Samuel 1.13-15).'),
('n1m4', 6, 'Je l''ai demandé à l''Éternel', 'Anne l''appela Samuel, « car, dit-elle, je l''ai demandé à l''Éternel » (1 Samuel 1.20).'),
('n1m4', 7, 'Vrai', 'Après la bénédiction d''Éli, Anne s''en alla, mangea, et son visage ne fut plus le même (1 Samuel 1.18) : la paix précède la réponse.'),
('n1m4', 8, 'Un temps où la parole de l''Éternel était rare', '« La parole de l''Éternel était rare en ce temps-là, les visions n''étaient pas fréquentes » (1 Samuel 3.1).'),
('n1m4', 9, 'Répondre : Parle, Éternel, car ton serviteur écoute', 'Éli lui dit : « si l''on t''appelle, tu diras : Parle, Éternel, car ton serviteur écoute » (1 Samuel 3.9).'),
('n1m4', 10, 'Obéir', 'Écouter Dieu, dans la Bible, c''est entendre et mettre en pratique ; c''est le mot de « Écoute, Israël ! » (Deutéronome 6.4).'),
('n1m4', 11, 'Elles entendent sa voix et le suivent', '« Mes brebis entendent ma voix ; je les connais, et elles me suivent » (Jean 10.27).'),
('n1m4', 12, 'Sa Parole écrite, la Bible', '« Toute Écriture est inspirée de Dieu, et utile pour enseigner… » (2 Timothée 3.16) ; tout autre moyen doit être vérifié par elle.'),
('n1m4', 13, 'Examiner cette parole à la lumière de l''Écriture et demander conseil à des croyants mûrs', '« Examinez toutes choses ; retenez ce qui est bon » (1 Thessaloniciens 5.21) ; le bon berger ne vend pas sa voix.'),
('n1m4', 14, 'Cesser de s''agiter, lâcher prise et reconnaître qui est Dieu', 'Le verbe râphâh signifie relâcher, cesser ; au milieu des bouleversements, Dieu invite à reconnaître sa souveraineté (Psaume 46.11).'),
('n1m4', 15, 'Pour montrer qu''il faut toujours prier, et ne point se relâcher', 'Luc l''annonce dès le premier verset : « pour montrer qu''il faut toujours prier, et ne point se relâcher » (Luc 18.1).'),
('n1m4', 16, 'Faux', 'Jésus raisonne par contraste : si un juge injuste finit par faire justice, combien plus Dieu fera-t-il justice à ses élus (Luc 18.6-8).'),
('n1m4', 17, 'Trois semaines', 'Daniel mena le deuil trois semaines entières ; le messager explique que le chef du royaume de Perse lui a résisté vingt et un jours (Daniel 10.2-3, 13).'),
('n1m4', 18, 'En gardant une apparence normale, pour le Père qui voit dans le secret', '« Parfume ta tête et lave ton visage, afin de ne pas montrer aux hommes que tu jeûnes, mais à ton Père qui est là dans le lieu secret » (Matthieu 6.17-18).'),
('n1m4', 19, 'Un jeûne qui libère les opprimés et partage le pain avec celui qui a faim', 'Dieu dit : « Voici le jeûne auquel je prends plaisir : Détache les chaînes de la méchanceté… Partage ton pain avec celui qui a faim » (Ésaïe 58.6-7).'),
('n1m5', 0, 'L''enseignement des apôtres, la communion fraternelle, la fraction du pain et les prières', '« Ils persévéraient dans l''enseignement des apôtres, dans la communion fraternelle, dans la fraction du pain, et dans les prières » (Actes 2.42).'),
('n1m5', 1, 'Une assemblée de personnes convoquées', 'L''ekklêsia est l''assemblée de ceux que Dieu a appelés en Christ ; l''Église n''est pas un bâtiment mais un peuple (1 Pierre 2.9).'),
('n1m5', 2, 'Trois mille', '« Ceux qui acceptèrent sa parole furent baptisés ; et, en ce jour-là, furent ajoutées environ trois mille âmes » (Actes 2.41).'),
('n1m5', 3, 'Il n''en est pas moins du corps', 'Paul demande : « ne serait-il pas du corps pour cela ? » (1 Corinthiens 12.15) : chaque membre est nécessaire, même s''il n''a pas le don des autres.'),
('n1m5', 4, 'Tous les membres souffrent avec lui', '« Si un membre souffre, tous les membres souffrent avec lui ; si un membre est honoré, tous les membres se réjouissent avec lui » (1 Corinthiens 12.26).'),
('n1m5', 5, 'De ne pas l''abandonner, comme c''est la coutume de quelques-uns', '« N''abandonnons pas notre assemblée, comme c''est la coutume de quelques-uns ; mais exhortons-nous réciproquement » (Hébreux 10.25).'),
('n1m5', 6, 'Faux', 'Le croyant est membre d''un corps (1 Corinthiens 12.27) et appelé à ne pas abandonner l''assemblée (Hébreux 10.25) ; l''isolement volontaire l''affaiblit.'),
('n1m5', 7, 'Faites des disciples', 'En grec, le verbe principal est « faites des disciples » (mathêteuô), accompagné de « allez », « baptisant » et « enseignant ».'),
('n1m5', 8, 'Plonger, immerger', 'Baptizô signifie plonger, immerger ; Paul y voit l''image de l''ensevelissement et de la résurrection avec Christ (Romains 6.4).'),
('n1m5', 9, 'Notre union avec Christ dans sa mort et sa résurrection pour une vie nouvelle', '« Nous avons donc été ensevelis avec lui par le baptême en sa mort, afin que… nous aussi nous marchions en nouveauté de vie » (Romains 6.4).'),
('n1m5', 10, 'Ésaïe 53', 'Il lisait : « Il a été mené comme une brebis à la boucherie… » (Ésaïe 53.7-8, cité en Actes 8.32-33), et Philippe lui annonça Jésus à partir de ce passage.'),
('n1m5', 11, '« Qu''est-ce qui empêche que je sois baptisé ? »', '« Voici de l''eau ; qu''est-ce qui empêche que je sois baptisé ? » (Actes 8.36) : le baptême suit de près la foi en Jésus.'),
('n1m5', 12, 'Nous sommes sauvés par grâce par la foi, et le baptême est l''obéissance et le témoignage public de cette foi', 'Le salut est par grâce, par la foi (Éphésiens 2.8-9) ; le baptême, commandé par Jésus (Matthieu 28.19), est « l''engagement d''une bonne conscience envers Dieu » (1 Pierre 3.21).'),
('n1m5', 13, 'Faux', 'La majorité pratique le baptême des croyants, mais d''autres évangéliques (réformés, presbytériens, anglicans) baptisent aussi les enfants de croyants ; on en parle avec respect.'),
('n1m5', 14, 'La Pâque', 'Jésus dit : « J''ai désiré vivement manger cette Pâque avec vous, avant de souffrir » (Luc 22.15) ; « Christ, notre Pâque, a été immolé » (1 Corinthiens 5.7).'),
('n1m5', 15, 'Le sang de l''agneau sur les portes', '« Le sang vous servira de signe sur les maisons où vous serez ; je verrai le sang, et je passerai par-dessus vous » (Exode 12.13).'),
('n1m5', 16, 'La nouvelle alliance dans le sang de Jésus, répandu pour nous', '« Cette coupe est la nouvelle alliance en mon sang, qui est répandu pour vous » (Luc 22.20), selon la promesse de Jérémie 31.31-34.'),
('n1m5', 17, 'Nous annonçons la mort du Seigneur jusqu''à ce qu''il vienne', '« Toutes les fois que vous mangez ce pain et que vous buvez cette coupe, vous annoncez la mort du Seigneur, jusqu''à ce qu''il vienne » (1 Corinthiens 11.26).'),
('n1m5', 18, 'Les riches mangeaient sans attendre les pauvres, et certains s''enivraient', '« L''un a faim, tandis que l''autre est ivre… faites-vous honte à ceux qui n''ont rien ? » (1 Corinthiens 11.21-22) : le mépris des frères rendait le repas indigne.'),
('n1m5', 19, 'S''éprouver soi-même et chercher d''abord à se réconcilier', 'Jésus dit : « va d''abord te réconcilier avec ton frère » (Matthieu 5.24), et Paul : « Que chacun donc s''éprouve soi-même » (1 Corinthiens 11.28).'),
('n1m6', 0, 'Faux', 'Jésus « a été tenté comme nous en toutes choses, sans commettre de péché » (Hébreux 4.15) ; le péché commence quand la convoitise est accueillie et « conçoit » (Jacques 1.15).'),
('n1m6', 1, 'De notre propre convoitise, qui nous attire et nous amorce', '« Dieu… ne tente lui-même personne. Mais chacun est tenté quand il est attiré et amorcé par sa propre convoitise » (Jacques 1.13-14).'),
('n1m6', 2, 'La convoitise conçoit et enfante le péché ; le péché consommé produit la mort', '« La convoitise, lorsqu''elle a conçu, enfante le péché ; et le péché, étant consommé, produit la mort » (Jacques 1.15).'),
('n1m6', 3, 'Que Dieu, fidèle, ne permettra pas de tentation au-delà de ses forces et préparera le moyen d''en sortir', '« Dieu, qui est fidèle, ne permettra pas que vous soyez tentés au delà de vos forces ; mais avec la tentation il préparera aussi le moyen d''en sortir » (1 Corinthiens 10.13).'),
('n1m6', 4, 'Des citations de l''Écriture : « Il est écrit »', 'Jésus a répondu trois fois par le Deutéronome : « Il est écrit » (Matthieu 4.4, 7, 10).'),
('n1m6', 5, 'Changer des pierres en pains', '« Si tu es Fils de Dieu, ordonne que ces pierres deviennent des pains » ; Jésus répond : « L''homme ne vivra pas de pain seulement » (Matthieu 4.3-4).'),
('n1m6', 6, 'Il cite lui-même un psaume en le détournant de son sens', 'Le diable cite le Psaume 91.11-12 pour pousser Jésus à se jeter du haut du temple ; Jésus répond : « Tu ne tenteras point le Seigneur, ton Dieu » (Matthieu 4.6-7).'),
('n1m6', 7, 'La convoitise de la chair, la convoitise des yeux et l''orgueil de la vie', '« Tout ce qui est dans le monde, la convoitise de la chair, la convoitise des yeux, et l''orgueil de la vie, ne vient point du Père » (1 Jean 2.16).'),
('n1m6', 8, 'Ce serait pécher contre Dieu', '« Comment ferais-je un aussi grand mal et pécherais-je contre Dieu ? » (Genèse 39.9).'),
('n1m6', 9, 'Il lui laisse son vêtement et s''enfuit dehors', '« Il lui laissa son vêtement dans la main, et s''enfuit au dehors » (Genèse 39.12) : certaines tentations ne se combattent pas, elles se fuient.'),
('n1m6', 10, 'En marchant selon l''Esprit', '« Marchez selon l''Esprit, et vous n''accomplirez pas les désirs de la chair » (Galates 5.16).'),
('n1m6', 11, 'La tempérance (maîtrise de soi)', 'Le fruit de l''Esprit est « l''amour, la joie, la paix, la patience, la bonté, la bénignité, la fidélité, la douceur, la tempérance » (Galates 5.22-23).'),
('n1m6', 12, 'Afin de ne pas pécher contre Dieu', '« Je serre ta parole dans mon cœur, afin de ne pas pécher contre toi » (Psaume 119.11).'),
('n1m6', 13, 'Les fuir, et rechercher la justice avec ceux qui invoquent le Seigneur d''un cœur pur', '« Fuis les passions de la jeunesse, et recherche la justice, la foi, la charité, la paix, avec ceux qui invoquent le Seigneur d''un cœur pur » (2 Timothée 2.22).'),
('n1m6', 14, 'Se soumettre à Dieu, puis résister au diable', '« Soumettez-vous donc à Dieu ; résistez au diable, et il fuira loin de vous » (Jacques 4.7).'),
('n1m6', 15, 'Il est fidèle et juste pour nous pardonner et nous purifier de toute iniquité', '« Si nous confessons nos péchés, il est fidèle et juste pour nous les pardonner, et pour nous purifier de toute iniquité » (1 Jean 1.9).'),
('n1m6', 16, 'Jésus-Christ le juste', '« Si quelqu''un a péché, nous avons un avocat auprès du Père, Jésus-Christ le juste » (1 Jean 2.1).'),
('n1m6', 17, 'Pierre est revenu vers Jésus et les disciples au lieu de s''enfermer dans le désespoir', 'Pierre pleura amèrement mais resta avec les disciples et fut restauré (Luc 22.62 ; Jean 21.15-17) ; Judas, rempli de remords, s''isola et se donna la mort (Matthieu 27.3-5).'),
('n1m6', 18, 'Trois fois', 'Trois fois, comme les trois reniements ; à chaque réponse, Jésus confie à Pierre la mission de paître ses brebis (Jean 21.15-17).'),
('n1m6', 19, 'La conviction vient de l''Esprit et conduit à la repentance et à la restauration ; la condamnation écrase et éloigne de Dieu', '« La tristesse selon Dieu produit une repentance à salut… tandis que la tristesse du monde produit la mort » (2 Corinthiens 7.10) ; « il n''y a donc maintenant aucune condamnation pour ceux qui sont en Jésus-Christ » (Romains 8.1).'),
('n2m1', 0, 'À son image', '« Dieu créa l''homme à son image… il créa l''homme et la femme » (Genèse 1.27).'),
('n2m1', 1, 'Une représentation, un reflet, une statue', 'Tselem désigne une représentation : l''homme représente Dieu sur la terre et reflète quelque chose de lui.'),
('n2m1', 2, 'Gouverner, cultiver et garder la création au nom de Dieu', 'Dieu demande à l''homme de dominer sur la terre et place Adam dans le jardin « pour le cultiver et pour le garder » (Genèse 2.15).'),
('n2m1', 3, 'Parce qu''il est une créature si merveilleuse, œuvre admirable de Dieu', '« Je te loue de ce que je suis une créature si merveilleuse. Tes œuvres sont admirables » (Psaume 139.14).'),
('n2m1', 4, 'Dans le pressoir, où il battait le blé en cachette', 'Gédéon battait le froment au pressoir pour le soustraire aux Madianites (Juges 6.11-12).'),
('n2m1', 5, 'Sur sa présence : « Je serai avec toi »', 'L''Éternel lui dit : « Je serai avec toi, et tu battras Madian comme un seul homme » (Juges 6.16).'),
('n2m1', 6, 'Il est l''image du Dieu invisible', '« Il est l''image du Dieu invisible, le premier-né de toute la création » (Colossiens 1.15) ; en lui, l''image de Dieu est restaurée en nous.'),
('n2m1', 7, 'Faux', 'Faux : le péché a abîmé l''image de Dieu, mais Genèse 9.6 et Jacques 3.9 affirment que l''homme la porte encore.'),
('n2m1', 8, 'L''adoption, le placement comme fils', 'Huiothesia désigne l''adoption : un nouveau nom, une nouvelle famille et les pleins droits d''héritier.'),
('n2m1', 9, 'La rédemption par son sang, la rémission des péchés', '« En lui nous avons la rédemption par son sang, la rémission des péchés, selon la richesse de sa grâce » (Éphésiens 1.7).'),
('n2m1', 10, 'Le sceau et le gage de notre héritage', 'Les croyants ont été « scellés du Saint-Esprit qui avait été promis, lequel est un gage de notre héritage ».'),
('n2m1', 11, '« Abba ! Père ! »', '« Dieu a envoyé dans nos cœurs l''Esprit de son Fils, lequel crie : Abba ! Père ! » (Galates 4.6).'),
('n2m1', 12, 'Être traité comme l''un des ouvriers de son père', 'Il avait préparé de dire : « Traite-moi comme l''un de tes mercenaires » (Luc 15.19), mais le père le restaure comme fils.'),
('n2m1', 13, 'Que le fils est pleinement rétabli dans sa dignité de fils', 'Ces gestes honorent le fils, lui rendent l''autorité familiale et le distinguent des esclaves, qui marchaient pieds nus.'),
('n2m1', 14, 'Une mentalité d''ouvrier qui réclame son salaire', 'L''aîné pense en termes de mérite ; le père lui rappelle : « Tout ce que j''ai est à toi » (Luc 15.31).'),
('n2m1', 15, 'Une nouvelle créature', '« Si quelqu''un est en Christ, il est une nouvelle créature. Les choses anciennes sont passées » (2 Corinthiens 5.17).'),
('n2m1', 16, 'Elle tend un piège', '« La crainte des hommes tend un piège, mais celui qui se confie en l''Éternel est protégé » (Proverbes 29.25).'),
('n2m1', 17, 'Il craignait le peuple et avait écouté sa voix', 'Saül avoue : « Je craignais le peuple, et j''ai écouté sa voix » (1 Samuel 15.24).'),
('n2m1', 18, 'Il ne serait pas serviteur de Christ', '« Si je plaisais encore aux hommes, je ne serais pas serviteur de Christ » (Galates 1.10).'),
('n2m1', 19, 'Faux', 'Faux : « Il n''y a donc maintenant aucune condamnation pour ceux qui sont en Jésus-Christ » (Romains 8.1).'),
('n2m2', 0, 'Pour être les témoins de Jésus', '« Vous recevrez une puissance, le Saint-Esprit survenant sur vous, et vous serez mes témoins » (Actes 1.8).'),
('n2m2', 1, 'Jérusalem, la Judée, la Samarie et les extrémités de la terre', 'Ce programme sert de plan à tout le livre des Actes, de Jérusalem jusqu''à Rome.'),
('n2m2', 2, 'Ils persévéraient ensemble dans la prière', '« Tous d''un commun accord persévéraient dans la prière » dans la chambre haute (Actes 1.14).'),
('n2m2', 3, 'Un bruit comme celui d''un vent impétueux et des langues semblables à des langues de feu', 'Un bruit « comme celui d''un vent impétueux » remplit la maison, et des langues de feu se posèrent sur chacun d''eux.'),
('n2m2', 4, 'Repentez-vous, soyez baptisés au nom de Jésus-Christ, et vous recevrez le don du Saint-Esprit', 'Pierre appelle à la repentance et au baptême, avec la promesse du don du Saint-Esprit (Actes 2.38).'),
('n2m2', 5, 'Celui qui atteste ce qu''il a vu et entendu', 'Le témoin atteste ce qu''il a vu et entendu ; le mot a donné « martyr » en français.'),
('n2m2', 6, 'À l''ivresse du vin', '« Ne vous enivrez pas de vin : c''est de la débauche. Soyez, au contraire, remplis de l''Esprit » (Éphésiens 5.18).'),
('n2m2', 7, 'C''est un commandement pour tous, à recevoir de Dieu de façon continue', 'Impératif, pluriel, passif et présent : un appel adressé à tous à se laisser continuellement remplir par l''Esprit.'),
('n2m2', 8, 'Faux', 'Faux : « Si quelqu''un n''a pas l''Esprit de Christ, il ne lui appartient pas » (Romains 8.9).'),
('n2m2', 9, 'La renommée', 'La liste est : amour, joie, paix, patience, bonté, bénignité, fidélité, douceur, tempérance (Galates 5.22-23).'),
('n2m2', 10, 'Parce qu''il s''agit d''un seul caractère aux multiples aspects, celui de Christ', 'Le fruit est un caractère unifié, opposé aux « œuvres » multiples et désordonnées de la chair.'),
('n2m2', 11, 'Demeurer en Christ, le cep', '« Celui qui demeure en moi et en qui je demeure porte beaucoup de fruit, car sans moi vous ne pouvez rien faire » (Jean 15.5).'),
('n2m2', 12, 'Afin qu''ils portent encore plus de fruit', 'Le Vigneron émonde le sarment qui porte du fruit « afin qu''il porte encore plus de fruit » (Jean 15.2).'),
('n2m2', 13, 'Il a seulement coupé le pan de son manteau et a refusé de porter la main sur lui', 'David coupa le pan du manteau de Saül, mais refusa de porter la main sur « l''oint de l''Éternel » (1 Samuel 24.5-7).'),
('n2m2', 14, 'Une force maîtrisée et soumise à Dieu', 'Praütès évoque une force maîtrisée, comme celle d''un animal puissant mais dompté ; Jésus est « doux et humble de cœur ».'),
('n2m2', 15, 'Pour l''utilité commune', '« À chacun la manifestation de l''Esprit est donnée pour l''utilité commune » (1 Corinthiens 12.7).'),
('n2m2', 16, 'L''Esprit, qui les distribue à chacun comme il veut', '« Un seul et même Esprit opère toutes ces choses, les distribuant à chacun en particulier comme il veut. »'),
('n2m2', 17, 'De l''Esprit de Dieu, de sagesse, d''intelligence et de savoir pour toutes sortes d''ouvrages', 'Betsaleel fut rempli de l''Esprit de Dieu pour réaliser les ouvrages du tabernacle (Exode 31.3).'),
('n2m2', 18, 'Le mettre au service des autres comme un bon dispensateur', '« Que chacun de vous mette au service des autres le don qu''il a reçu », comme de bons dispensateurs de la grâce de Dieu.'),
('n2m2', 19, 'Vrai', 'Vrai : sans la charité, celui qui parle les langues des hommes et des anges n''est qu''« un airain qui résonne ».'),
('n2m3', 0, 'Que l''homme soit seul', '« Il n''est pas bon que l''homme soit seul ; je lui ferai une aide semblable à lui » (Genèse 2.18).'),
('n2m3', 1, 'Un secours, mot souvent employé pour Dieu lui-même', 'ʿÉzer désigne un secours ; la Bible l''emploie souvent pour Dieu, « notre aide », sans aucune idée d''infériorité.'),
('n2m3', 2, 'Quitter, s''attacher, devenir une seule chair', '« L''homme quittera son père et sa mère, et s''attachera à sa femme, et ils deviendront une seule chair » (Genèse 2.24).'),
('n2m3', 3, 'L''Éternel lui-même', '« L''Éternel a été témoin entre toi et la femme de ta jeunesse… la femme de ton alliance » (Malachie 2.14).'),
('n2m3', 4, 'Comme Christ a aimé l''Église et s''est livré pour elle', '« Maris, aimez vos femmes, comme Christ a aimé l''Église, et s''est livré lui-même pour elle » (Éphésiens 5.25).'),
('n2m3', 5, 'Se soumettre les uns aux autres dans la crainte de Christ', '« Vous soumettant les uns aux autres dans la crainte de Christ » (Éphésiens 5.21) : la soumission s''inscrit dans un cadre mutuel.'),
('n2m3', 6, 'Faux', 'Faux : le mari est appelé à aimer comme Christ et à ne pas s''aigrir contre sa femme (Colossiens 3.19) ; les victimes de violence doivent être protégées.'),
('n2m3', 7, 'Fabricants de tentes', 'Paul demeura chez eux et travailla avec eux, car ils étaient faiseurs de tentes (Actes 18.3).'),
('n2m3', 8, 'Ils l''ont pris avec eux et lui ont exposé plus exactement la voie de Dieu', '« Ils le prirent avec eux, et lui exposèrent plus exactement la voie de Dieu » (Actes 18.26).'),
('n2m3', 9, 'Comme deux dons particuliers de Dieu', '« Chacun tient de Dieu un don particulier, l''un d''une manière, l''autre d''une autre » (1 Corinthiens 7.7).'),
('n2m3', 10, 'Sa sanctification, et qu''il s''abstienne de l''impudicité', '« Ce que Dieu veut, c''est votre sanctification ; c''est que vous vous absteniez de l''impudicité » (1 Thessaloniciens 4.3).'),
('n2m3', 11, 'Toute relation sexuelle hors du mariage', 'Porneia est un terme large qui couvre toute relation sexuelle en dehors du mariage.'),
('n2m3', 12, 'Il ne voulait pas pécher contre Dieu', '« Comment ferais-je un aussi grand mal et pécherais-je contre Dieu ? » (Genèse 39.9).'),
('n2m3', 13, 'Il lui a laissé son vêtement et s''est enfui', '« Il lui laissa son vêtement dans la main, et s''enfuit au dehors » (Genèse 39.12).'),
('n2m3', 14, 'Ne pas réveiller l''amour avant qu''il le veuille', '« Ne réveillez pas, ne réveillez pas l''amour, avant qu''elle le veuille » (Cantique 2.7).'),
('n2m3', 15, 'À la maison, en voyage, au coucher et au lever', 'Moïse cite quatre moments ordinaires : à la maison, en voyage, au coucher et au lever, c''est-à-dire partout et tout le temps.'),
('n2m3', 16, 'Aiguiser par des passages répétés', 'Shanan signifie aiguiser : on transmet la foi par une répétition patiente, comme on affûte une lame.'),
('n2m3', 17, 'Parce qu''il honorait ses fils plus que Dieu et ne les réprimait pas', '« Pourquoi honores-tu tes fils plus que moi ? » (1 Samuel 2.29) ; Éli connaissait leur mal sans les réprimer (1 Samuel 3.13).'),
('n2m3', 18, 'D''irriter leurs enfants', '« Pères, n''irritez pas vos enfants, mais élevez-les en les corrigeant et en les instruisant selon le Seigneur » (Éphésiens 6.4).'),
('n2m3', 19, 'Vrai', 'Vrai : Paul évoque « la foi sincère… qui habita d''abord dans ton aïeule Loïs et dans ta mère Eunice » (2 Timothée 1.5).'),
('n2m4', 0, 'À l’Éternel', '« A l’Éternel la terre et ce qu’elle renferme » (Psaume 24.1) : Dieu est propriétaire parce qu’il est créateur.'),
('n2m4', 1, 'Celui qui gère la maison d’un autre et lui rend compte', 'L’oikonomos administre les biens de son maître ; c’est la position du chrétien face à ses biens (Luc 16.1-2).'),
('n2m4', 2, 'Dieu et Mamon', '« Vous ne pouvez servir Dieu et Mamon » (Matthieu 6.24) : Mamon désigne la richesse devenue un maître.'),
('n2m4', 3, 'Il l’a caché dans la terre', 'Par peur, il a creusé la terre et caché le talent de son maître (Matthieu 25.18, 25).'),
('n2m4', 4, 'La même louange : « C’est bien, bon et fidèle serviteur »', 'Le maître leur adresse exactement les mêmes paroles (Matthieu 25.21, 23) : il récompense la fidélité, non la comparaison des résultats.'),
('n2m4', 5, 'L’est aussi dans les grandes', '« Celui qui est fidèle dans les moindres choses l’est aussi dans les grandes » (Luc 16.10).'),
('n2m4', 6, 'L’amour de l’argent', 'Ce n’est pas l’argent lui-même, mais « l’amour de l’argent » qui est une racine de tous les maux (1 Timothée 6.10).'),
('n2m4', 7, 'Prendre ses deux enfants comme esclaves', '« Le créancier est venu pour prendre mes deux enfants et en faire ses esclaves » (2 Rois 4.1).'),
('n2m4', 8, 'Vendre l’huile, payer la dette et vivre du reste', '« Va vendre l’huile, et paie ta dette ; et tu vivras, toi et tes fils, de ce qui restera » (2 Rois 4.7).'),
('n2m4', 9, 'L’esclave de celui qui prête', '« Celui qui emprunte est l’esclave de celui qui prête » (Proverbes 22.7) : la dette restreint la liberté.'),
('n2m4', 10, 'À l’abondance', '« Les projets de l’homme diligent ne mènent qu’à l’abondance, mais celui qui agit avec précipitation n’arrive qu’à la disette. »'),
('n2m4', 11, 'Avec joie', '« Que chacun donne… sans tristesse ni contrainte ; car Dieu aime celui qui donne avec joie » (2 Corinthiens 9.7).'),
('n2m4', 12, 'Malgré leur pauvreté profonde, au-delà de leurs moyens et avec joie', 'Paul souligne leur joie et leur générosité au milieu de beaucoup de tribulations et malgré leur pauvreté profonde.'),
('n2m4', 13, 'Apportez-les à la maison du trésor et mettez-moi à l’épreuve', '« Apportez à la maison du trésor toutes les dîmes… Mettez-moi de la sorte à l’épreuve » (Malachie 3.10).'),
('n2m4', 14, 'Par donner à Dieu', 'Donner d’abord proclame que Dieu est premier (Proverbes 3.9), puis on épargne, on paie ses obligations et on vit avec le reste.'),
('n2m4', 15, 'Pour le cultiver et pour le garder', '« L’Éternel Dieu… le plaça dans le jardin d’Éden pour le cultiver et pour le garder » (Genèse 2.15), avant même le péché.'),
('n2m4', 16, 'Faux', 'Faux : le travail existait avant la chute (Genèse 2.15). Après le péché, c’est le sol qui est maudit et le travail devient pénible (Genèse 3.17-19).'),
('n2m4', 17, 'De bon cœur, comme pour le Seigneur', '« Tout ce que vous faites, faites-le de bon cœur, comme pour le Seigneur et non pour des hommes » (Colossiens 3.23).'),
('n2m4', 18, 'Faux', 'Faux : le texte vise celui qui ne veut pas travailler. Envers ceux qui ne peuvent pas, la Bible demande la solidarité.'),
('n2m4', 19, 'Prélever le cinquième des récoltes pendant l’abondance et le stocker', 'Joseph conseille de prélever le cinquième des récoltes pendant les sept années d’abondance et de les garder en réserve (Genèse 41.34-36).'),
('n2m5', 0, 'Septante fois sept fois', 'Jésus répond à Pierre : « Je ne te dis pas jusqu’à sept fois, mais jusqu’à septante fois sept fois », c’est-à-dire sans compter.'),
('n2m5', 1, 'Dix mille talents', 'Il devait dix mille talents, une dette impossible à rembourser, que le roi lui a entièrement remise (Matthieu 18.24, 27).'),
('n2m5', 2, 'Il le fait jeter en prison', 'Il le saisit à la gorge et le fait jeter en prison jusqu’à ce qu’il ait payé (Matthieu 18.28-30).'),
('n2m5', 3, 'Celui qui a reçu un immense pardon de Dieu doit pardonner aux autres', '« Ne devais-tu pas aussi avoir pitié de ton compagnon, comme j’ai eu pitié de toi ? » (Matthieu 18.33).'),
('n2m5', 4, 'Comme Dieu nous a pardonné en Christ', '« Vous pardonnant réciproquement, comme Dieu vous a pardonné en Christ » (Éphésiens 4.32).'),
('n2m5', 5, 'Remettre la dette à Dieu et renoncer à la vengeance', 'Pardonner, c’est renoncer à la vengeance et remettre la cause à Dieu, qui juge justement (Romains 12.19), sans nier le mal.'),
('n2m5', 6, '« Vous aviez médité de me faire du mal, Dieu l’a changé en bien »', 'Joseph nomme le mal et reconnaît que Dieu l’a changé en bien pour sauver la vie à un peuple nombreux (Genèse 50.20).'),
('n2m5', 7, 'Faux', 'Faux : le pardon dépend de moi, la réconciliation demande un vrai changement ; se mettre en sécurité est juste, comme David qui fuit Saül.'),
('n2m5', 8, 'Ne pas pécher et ne pas laisser le soleil se coucher sur sa colère', '« Si vous vous mettez en colère, ne péchez point ; que le soleil ne se couche pas sur votre colère » (Éphésiens 4.26).'),
('n2m5', 9, 'Que le péché se couche à la porte, mais qu’il doit dominer sur lui', '« Le péché se couche à la porte, et ses désirs se portent vers toi : mais toi, domine sur lui » (Genèse 4.7).'),
('n2m5', 10, 'Prompt à écouter, lent à parler, lent à se mettre en colère', '« Que tout homme soit prompt à écouter, lent à parler, lent à se mettre en colère ; car la colère de l’homme n’accomplit pas la justice de Dieu. »'),
('n2m5', 11, 'Faux', 'Faux : Jésus s’est indigné (Marc 3.5) et Paul dit « si vous vous mettez en colère, ne péchez point ». C’est ce que l’on fait de sa colère qui peut devenir péché.'),
('n2m5', 12, 'Il lui parle et l’exhorte à espérer en Dieu', '« Pourquoi t’abats-tu, mon âme… ? Espère en Dieu, car je le louerai encore » (Psaume 42.6).'),
('n2m5', 13, 'Faire connaître ses besoins à Dieu par la prière, avec des actions de grâces', '« Ne vous inquiétez de rien ; mais en toute chose faites connaître vos besoins à Dieu par des prières et des supplications, avec des actions de grâces. »'),
('n2m5', 14, 'Elle gardera nos cœurs et nos pensées en Jésus-Christ', 'La paix de Dieu « gardera vos cœurs et vos pensées en Jésus-Christ » ; le verbe évoque une garnison qui monte la garde.'),
('n2m5', 15, 'Sage', '« Celui qui fréquente les sages devient sage, mais celui qui se plaît avec les insensés s’en trouve mal » (Proverbes 13.20).'),
('n2m5', 16, 'Le reprendre entre lui et nous seuls', '« Va et reprends-le entre toi et lui seul. S’il t’écoute, tu as gagné ton frère » (Matthieu 18.15).'),
('n2m5', 17, 'S’il est possible, autant que cela dépend de nous', '« S’il est possible, autant que cela dépend de vous, soyez en paix avec tous les hommes » : je suis responsable de ma part.'),
('n2m5', 18, 'Il lui a donné son manteau, ses vêtements et ses armes', 'Jonathan se dépouilla de son manteau, de ses vêtements, de son épée, de son arc et de sa ceinture pour les donner à David.'),
('n2m5', 19, 'Il s’est enfui pour se mettre en sécurité', 'Averti par le signal des flèches, David s’est enfui (1 Samuel 20.35-42) : se protéger d’une personne violente est sage.'),
('n2m6', 0, 'Le temple du Saint-Esprit', '« Votre corps est le temple du Saint-Esprit qui est en vous » (1 Corinthiens 6.19).'),
('n2m6', 1, 'Parce que nous avons été rachetés à un grand prix', '« Vous avez été rachetés à un grand prix. Glorifiez donc Dieu dans votre corps » : le prix est le sang de Christ.'),
('n2m6', 2, 'Le sanctuaire où Dieu habite', 'Naos désigne le sanctuaire lui-même, le lieu de la présence de Dieu, et non l’ensemble des bâtiments du temple.'),
('n2m6', 3, 'Des légumes et de l’eau', 'Daniel demande : « qu’on nous donne des légumes à manger et de l’eau à boire » (Daniel 1.12).'),
('n2m6', 4, 'L’exercice corporel est utile à peu de chose, la piété est utile à tout', '« L’exercice corporel est utile à peu de chose, tandis que la piété est utile à tout » : une hiérarchie, pas une opposition.'),
('n2m6', 5, 'Est compatible avec la prière et la foi', 'Luc était « le médecin bien-aimé » (Colossiens 4.14) ; Dieu peut guérir par des moyens ordinaires ou extraordinaires.'),
('n2m6', 6, 'Faux', 'Faux : c’est un souhait de Jean pour Gaïus, selon une formule de salutation courante, qui montre le souci des apôtres pour la santé de leurs frères.'),
('n2m6', 7, 'Sur le fait qu’il s’est reposé le septième jour après la création', '« En six jours l’Éternel a fait les cieux, la terre et la mer… et il s’est reposé le septième jour » (Exode 20.11).'),
('n2m6', 8, 'Le souvenir de l’esclavage en Égypte et de la délivrance', '« Tu te souviendras que tu as été esclave au pays d’Égypte… c’est pourquoi l’Éternel, ton Dieu, t’a ordonné d’observer le jour du repos. »'),
('n2m6', 9, 'On en ramassait une double portion pour le jour du repos', 'Le sixième jour, chacun ramassait le double, car le septième jour il n’y avait pas de manne (Exode 16.22-26).'),
('n2m6', 10, 'Le sabbat a été fait pour l’homme, et non l’homme pour le sabbat', '« Le sabbat a été fait pour l’homme, et non l’homme pour le sabbat » : le repos est un don pour le bien de l’homme.'),
('n2m6', 11, 'Venez à l’écart dans un lieu désert, et reposez-vous un peu', 'Ils n’avaient « pas même le temps de manger » ; Jésus les invite à se reposer à l’écart (Marc 6.31).'),
('n2m6', 12, 'À ceux qui sont fatigués et chargés et qui viennent à lui', '« Venez à moi, vous tous qui êtes fatigués et chargés, et je vous donnerai du repos » (Matthieu 11.28).'),
('n2m6', 13, 'Faux', 'Faux : Dieu lui-même s’est reposé et a commandé le repos. Le paresseux refuse de travailler ; celui qui se repose fait confiance à Dieu.'),
('n2m6', 14, 'Parce que la reine Jézabel menace de le tuer', 'Jézabel lui envoie un message de mort ; Élie a peur et s’enfuit pour sauver sa vie (1 Rois 19.1-3).'),
('n2m6', 15, 'Il l’a fait dormir et manger', 'Un ange le touche deux fois et lui dit : « Lève-toi, mange, car le chemin est trop long pour toi » (1 Rois 19.5-7).'),
('n2m6', 16, 'Dans un murmure doux et léger', 'L’Éternel n’était ni dans le vent, ni dans le tremblement de terre, ni dans le feu ; après le feu vint « un murmure doux et léger » (1 Rois 19.11-12).'),
('n2m6', 17, 'En lui révélant qu’il s’était réservé sept mille hommes fidèles', 'Dieu révèle qu’il s’est réservé en Israël sept mille hommes qui n’ont pas fléchi le genou devant Baal (1 Rois 19.18).'),
('n2m6', 18, 'De ceux qui ont le cœur brisé', '« L’Éternel est près de ceux qui ont le cœur brisé, et il sauve ceux qui ont l’esprit dans l’abattement » (Psaume 34.19).'),
('n2m6', 19, 'Faux', 'Faux : Élie, Job, Jérémie, David et Paul ont connu de grandes détresses. Demander de l’aide est un acte de sagesse (Galates 6.2).'),
('n3m1', 0, 'Ils sont créés à l’image de Dieu', '« Dieu créa l’homme à son image… il créa l’homme et la femme » (Genèse 1.27) : tous deux portent également l’image de Dieu.'),
('n3m1', 1, '« Dieu a-t-il réellement dit… ? »', 'Le serpent commence par mettre en doute la parole de Dieu (Genèse 3.1). « Où es-tu ? » est la question de Dieu à Adam (Genèse 3.9).'),
('n3m1', 2, 'Créer, une œuvre que seul Dieu accomplit', 'Dans l’Ancien Testament, bārā’ a toujours Dieu pour sujet : il désigne l’acte créateur que lui seul peut accomplir.'),
('n3m1', 3, 'Par la foi', '« C’est par la foi que nous reconnaissons que le monde a été formé par la parole de Dieu » (Hébreux 11.3).'),
('n3m1', 4, 'Par un seul homme', '« Par un seul homme le péché est entré dans le monde, et par le péché la mort » (Romains 5.12).'),
('n3m1', 5, 'Genèse 3.15', 'En Genèse 3.15, Dieu annonce que la postérité de la femme écrasera la tête du serpent : une promesse accomplie en Christ.'),
('n3m1', 6, 'Création, chute, rédemption, restauration', 'La Bible raconte la création bonne, la chute de l’homme, la rédemption en Christ et la restauration de toutes choses (Apocalypse 21.5).'),
('n3m1', 7, 'Être déclaré juste par Dieu par la foi en Christ', 'Justifier (grec dikaioō) signifie déclarer juste : « ils sont gratuitement justifiés par sa grâce » (Romains 3.24).'),
('n3m1', 8, 'La transformation progressive du croyant par le Saint-Esprit', 'La sanctification est l’œuvre continue de l’Esprit qui nous rend semblables à Christ ; elle découle de la justification sans la remplacer.'),
('n3m1', 9, 'Un seul : Jésus-Christ homme', '« Il y a un seul Dieu, et aussi un seul médiateur entre Dieu et les hommes, Jésus-Christ homme » (1 Timothée 2.5).'),
('n3m1', 10, 'Jésus a pris notre place et porté notre péché', '« Celui qui n’a point connu le péché, il l’a fait devenir péché pour nous, afin que nous devenions en lui justice de Dieu » (2 Corinthiens 5.21).'),
('n3m1', 11, 'Le publicain', 'Jésus conclut : « celui-ci [le publicain] descendit dans sa maison justifié, plutôt que l’autre » (Luc 18.14).'),
('n3m1', 12, 'Avec son propre sang', 'Christ est entré « une fois pour toutes dans le lieu très saint, non avec le sang des boucs et des veaux, mais avec son propre sang » (Hébreux 9.12).'),
('n3m1', 13, 'Selon sa miséricorde', '« Il nous a sauvés, non à cause des œuvres de justice que nous aurions faites, mais selon sa miséricorde » (Tite 3.5).'),
('n3m1', 14, 'Vrai', 'Romains 8.30 relie appel, justification et glorification en une chaîne que rien ne brise : « ceux qu’il a justifiés, il les a aussi glorifiés ».'),
('n3m1', 15, 'Les portes du séjour des morts', '« Je bâtirai mon Église, et les portes du séjour des morts ne prévaudront point contre elle » (Matthieu 16.18).'),
('n3m1', 16, 'Une assemblée de personnes convoquées', 'L’ekklēsia est l’assemblée de ceux que Dieu appelle ; l’Église est un peuple avant d’être un lieu.'),
('n3m1', 17, 'Il est triste, mais pas comme ceux qui n’ont point d’espérance', 'Paul écrit « afin que vous ne vous affligiez pas comme les autres qui n’ont point d’espérance » : le chrétien pleure, mais avec espérance.'),
('n3m1', 18, '« Je suis la résurrection et la vie »', '« Je suis la résurrection et la vie. Celui qui croit en moi vivra, quand même il serait mort » (Jean 11.25).'),
('n3m1', 19, 'Un nouveau ciel et une nouvelle terre où Dieu habite avec les hommes', 'Jean voit « un nouveau ciel et une nouvelle terre » et entend : « Voici le tabernacle de Dieu avec les hommes ! » (Apocalypse 21.1-3).'),
('n3m2', 0, 'Un texte hors contexte peut dire le contraire de son sens', 'Un texte sans contexte devient un prétexte : le diable lui-même a cité le Psaume 91 en le détournant (Matthieu 4.6).'),
('n3m2', 1, 'Le Psaume 91', 'Le diable cite le Psaume 91.11-12 en omettant « dans toutes tes voies » et en le transformant en invitation à tenter Dieu.'),
('n3m2', 2, '« Il est aussi écrit : Tu ne tenteras point le Seigneur, ton Dieu »', 'Jésus interprète l’Écriture par l’Écriture en citant Deutéronome 6.16.'),
('n3m2', 3, 'Ils examinaient chaque jour les Écritures pour vérifier ce qu’on leur disait', 'Ils reçurent la parole avec empressement et examinaient chaque jour les Écritures « pour voir si ce qu’on leur disait était exact ».'),
('n3m2', 4, 'Ils en donnaient le sens pour faire comprendre ce qui était lu', '« Ils en donnaient le sens pour faire comprendre ce qu’ils avaient lu » (Néhémie 8.8).'),
('n3m2', 5, 'Couper droit, tracer un chemin droit', 'Orthotomeō signifie couper droit : l’interprète fidèle trace un chemin droit à travers le texte.'),
('n3m2', 6, 'D’apprendre le contentement dans l’abondance comme dans la disette', 'Les versets 11-12 parlent de savoir vivre dans l’humiliation et dans l’abondance : Christ fortifie Paul dans toutes les situations.'),
('n3m2', 7, 'Aux exilés de Babylone, qui devaient y rester soixante-dix ans', 'Le verset suit l’annonce que l’exil durera soixante-dix ans (Jérémie 29.10) : la promesse inclut une longue attente.'),
('n3m2', 8, 'Comme une affaire réelle à juger', 'David s’indigne et condamne le riche, jusqu’à ce que Nathan lui dise : « Tu es cet homme-là ! » (2 Samuel 12.7).'),
('n3m2', 9, 'Des principes généraux de sagesse', 'Un māshāl est une maxime de sagesse qui dit ce qui arrive généralement ; Proverbes 26.4-5 montre qu’il faut discerner quand l’appliquer.'),
('n3m2', 10, 'Que la sagesse consiste à discerner quelle maxime s’applique à chaque situation', 'Les proverbes ne sont pas des règles mécaniques : parfois il faut se taire, parfois répondre, selon la situation.'),
('n3m2', 11, 'Le parallélisme des idées d’une ligne à l’autre', 'La poésie hébraïque reprend, prolonge ou oppose une idée dans la ligne suivante : « Il me fait reposer… Il me dirige… ».'),
('n3m2', 12, 'Les sept Églises', '« Les sept étoiles sont les anges des sept Églises, et les sept chandeliers sont les sept Églises » (Apocalypse 1.20).'),
('n3m2', 13, 'Faux', 'Faux. La Bible raconte par exemple l’adultère de David, mais précise : « Ce que David avait fait déplut à l’Éternel » (2 Samuel 11.27).'),
('n3m2', 14, 'Par Moïse et par tous les prophètes', '« Et, commençant par Moïse et par tous les prophètes, il leur expliqua dans toutes les Écritures ce qui le concernait » (Luc 24.27).'),
('n3m2', 15, 'De Jésus-Christ', '« Vous sondez les Écritures… ce sont elles qui rendent témoignage de moi » (Jean 5.39).'),
('n3m2', 16, 'Sens premier, principe intemporel, application', 'Hier, toujours, aujourd’hui : ce que le texte signifiait, le principe qui demeure, puis son application à notre vie.'),
('n3m2', 17, 'Qu’on utilise les passages clairs pour éclairer les passages difficiles', 'Puisque toute l’Écriture vient du même Dieu, on éclaire les textes obscurs par les textes clairs, sans bâtir de doctrine sur un verset isolé.'),
('n3m2', 18, 'Prendre des mesures pour protéger la sécurité des autres, par exemple autour d’une piscine ou sur un chantier', 'Le principe : je suis responsable de la sécurité de ceux qui sont affectés par mes biens et mes actes, par amour du prochain.'),
('n3m2', 19, 'À un homme qui se regarde dans un miroir puis oublie son visage', 'Jacques compare l’auditeur oublieux à un homme qui se regarde dans un miroir et oublie aussitôt quel il était (Jacques 1.23-24).'),
('n3m3', 0, 'Faire de toutes les nations des disciples', '« Allez, faites de toutes les nations des disciples, les baptisant… et enseignez-leur à observer tout ce que je vous ai prescrit » (Matthieu 28.19-20).'),
('n3m3', 1, 'Sur l’autorité de Jésus, à qui tout pouvoir a été donné dans le ciel et sur la terre', '« Tout pouvoir m’a été donné dans le ciel et sur la terre. Allez… » : la mission découle de l’autorité de Christ.'),
('n3m3', 2, '« Je suis avec vous tous les jours, jusqu’à la fin du monde »', 'Matthieu termine son Évangile par la présence de Jésus avec ses disciples, comme il l’avait commencé avec « Emmanuel, Dieu avec nous ».'),
('n3m3', 3, 'Tous les disciples', 'Jésus dit à tous ses disciples : « vous serez mes témoins » (Actes 1.8) ; dans les Actes, les croyants dispersés annonçaient la parole partout (Actes 8.4).'),
('n3m3', 4, 'La puissance du Saint-Esprit survenant sur eux', '« Vous recevrez une puissance, le Saint-Esprit survenant sur vous, et vous serez mes témoins » (Actes 1.8).'),
('n3m3', 5, 'Jérusalem, la Judée, la Samarie, les extrémités de la terre', '« À Jérusalem, dans toute la Judée, dans la Samarie, et jusqu’aux extrémités de la terre » : un plan qui structure tout le livre des Actes.'),
('n3m3', 6, 'Dans sa maison, vers les siens, pour raconter ce que le Seigneur a fait', '« Va dans ta maison, vers les tiens, et raconte-leur tout ce que le Seigneur t’a fait, et comment il a eu pitié de toi » (Marc 5.19).'),
('n3m3', 7, 'Ils ne le peuvent pas : il faut que quelqu’un prêche', 'Paul établit une chaîne : être envoyé, prêcher, entendre, croire, invoquer. « Comment en entendront-ils parler, s’il n’y a personne qui prêche ? »'),
('n3m3', 8, 'Celui qui atteste ce qu’il a vu et vécu', 'Le témoin raconte ce qu’il a vu ; le mot a aussi donné « martyr », pour ceux qui ont scellé leur témoignage de leur vie.'),
('n3m3', 9, 'Christ est mort pour nos péchés, a été enseveli et est ressuscité le troisième jour', '« Christ est mort pour nos péchés, selon les Écritures ; il a été enseveli, et il est ressuscité le troisième jour, selon les Écritures. »'),
('n3m3', 10, 'Avec douceur et respect', '« Étant toujours prêts à vous défendre, avec douceur et respect, devant quiconque vous demande raison de l’espérance qui est en vous. »'),
('n3m3', 11, 'Une plaidoirie, une défense raisonnée', 'Apologia est la défense présentée au tribunal ; il a donné « apologétique », l’explication raisonnée de la foi.')
